function getSectionStyle(key){STATE.appearance=STATE.appearance||{};STATE.appearance.sectionStyles=STATE.appearance.sectionStyles||{};if(!STATE.appearance.sectionStyles[key])STATE.appearance.sectionStyles[key]={layout:(DESIGN_LAYOUTS[key]?.[0]?.[0]||'default'),font:'Inter,system-ui,-apple-system,"Segoe UI",sans-serif',headingFont:'Georgia,"Times New Roman",serif',bodyColor:'',headingColor:'',accentColor:'',fontSize:'1rem',headingSize:'',lineHeight:'1.65',letterSpacing:'0px',headingWeight:'700',hoverEnabled:true,hoverColor:'',linkEnabled:true,linkUnderline:false,paragraphImage:'',paragraphImageEnabled:false,paragraphImagePosition:'right',paragraphImageWidth:'34%',backgroundEnabled:true,backgroundColor:'transparent',backgroundImage:'',backgroundOpacity:'1',backgroundBlur:'0px',backgroundBrightness:'1',backgroundContrast:'1',backgroundSaturate:'1',overlayColor:'transparent',overlayOpacity:'0',borderColor:'',borderRadius:'16px',shadow:'0 18px 45px rgba(0,0,0,.08)',paddingTop:'',paddingBottom:'',sectionMaxWidth:'',customClass:'',ctaEnabled:false,ctaLabel:'Learn more',ctaUrl:'#',backgroundPosition:'center',backgroundSize:'cover'};return STATE.appearance.sectionStyles[key]}
function designSelect(id,options,current){return `<select id="${id}">${options.map(([v,l])=>`<option value="${attr(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('')}</select>`}
function designPanel(view){if(!DESIGN_LAYOUTS[view])return '';const st=getSectionStyle(view), layouts=DESIGN_LAYOUTS[view];return `<div class="card premium-design-panel" data-design-view="${esc(view)}"><h2>Premium ${esc(VIEWS[view]?.[0]||view)} Design Studio</h2><p class="sub">Edit appearance without touching code. Content stays separate from design, so you can safely change colors, typography, background, links, imagery and layout.</p><div class="design-tabs"><span>Layout</span><span>Typography</span><span>Background</span><span>Interactions</span><span>Content media</span></div><div class="grid two"><div class="field"><label>Structure / layout preset — 10 professional options</label>${designSelect('ds_layout',layouts,st.layout)}</div><div class="field"><label>Section max width</label><input id="ds_width" value="${attr(st.sectionMaxWidth||'')}" placeholder="e.g. 1180px or 92%"></div><div class="field"><label>Body font — 76 premium presets</label>${designSelect('ds_font',DESIGN_FONTS,st.font)}</div><div class="field"><label>Heading font</label>${designSelect('ds_heading_font',DESIGN_FONTS,st.headingFont)}</div><div class="field"><label>Body text color</label><input id="ds_body_color" type="color" value="${attr(st.bodyColor||'#1A1712')}"></div><div class="field"><label>Heading color</label><input id="ds_heading_color" type="color" value="${attr(st.headingColor||'#1A1712')}"></div><div class="field"><label>Accent color</label><input id="ds_accent_color" type="color" value="${attr(st.accentColor||'#C9A227')}"></div><div class="field"><label>Body font size</label><input id="ds_size" value="${attr(st.fontSize||'1rem')}" placeholder="e.g. 1rem / 17px"></div><div class="field"><label>Heading size</label><input id="ds_heading_size" value="${attr(st.headingSize||'')}" placeholder="e.g. clamp(2rem,4vw,4rem)"></div><div class="field"><label>Line height</label><input id="ds_line" value="${attr(st.lineHeight||'1.65')}"></div><div class="field"><label>Letter spacing</label><input id="ds_letter" value="${attr(st.letterSpacing||'0px')}"></div><div class="field"><label>Heading weight</label><select id="ds_weight">${[400,500,600,700,800,900].map(x=>`<option value="${x}" ${String(st.headingWeight||700)===String(x)?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Background color</label><input id="ds_bg_color" type="color" value="${attr(st.backgroundColor&&st.backgroundColor.startsWith('#')?st.backgroundColor:'#FFFFFF')}"></div><div class="field"><label>Background image path</label><input id="ds_bg_image" value="${attr(st.backgroundImage||'')}" placeholder="Optional image from Media Library"></div><div class="field"><label>Background opacity</label><input id="ds_bg_opacity" type="number" min="0" max="1" step="0.01" value="${attr(st.backgroundOpacity??1)}"></div><div class="field"><label>Background blur</label><input id="ds_bg_blur" value="${attr(st.backgroundBlur||'0px')}" placeholder="0px–20px"></div><div class="field"><label>Brightness</label><input id="ds_brightness" type="range" min="0.4" max="1.8" step="0.05" value="${attr(st.backgroundBrightness||1)}"></div><div class="field"><label>Contrast</label><input id="ds_contrast" type="range" min="0.5" max="1.8" step="0.05" value="${attr(st.backgroundContrast||1)}"></div><div class="field"><label>Saturation</label><input id="ds_saturate" type="range" min="0" max="2" step="0.05" value="${attr(st.backgroundSaturate||1)}"></div><div class="field"><label>Overlay opacity</label><input id="ds_overlay_opacity" type="number" min="0" max="1" step="0.01" value="${attr(st.overlayOpacity??0)}"></div><div class="field"><label>Border radius</label><input id="ds_radius" value="${attr(st.borderRadius||'16px')}"></div><div class="field"><label>Shadow</label><input id="ds_shadow" value="${attr(st.shadow||'0 18px 45px rgba(0,0,0,.08)')}"></div></div><div class="grid three"><div class="field"><label>Hover effect</label><select id="ds_hover"><option value="on" ${st.hoverEnabled!==false?'selected':''}>On</option><option value="off" ${st.hoverEnabled===false?'selected':''}>Off</option></select></div><div class="field"><label>Hover color</label><input id="ds_hover_color" type="color" value="${attr(st.hoverColor||'#C9A227')}"></div><div class="field"><label>Links</label><select id="ds_links"><option value="on" ${st.linkEnabled!==false?'selected':''}>Enabled</option><option value="off" ${st.linkEnabled===false?'selected':''}>Disabled</option></select></div><div class="field"><label>Link underline</label><select id="ds_underline"><option value="on" ${st.linkUnderline?'selected':''}>On</option><option value="off" ${!st.linkUnderline?'selected':''}>Off</option></select></div><div class="field"><label>Paragraph image</label><select id="ds_pimg_enabled"><option value="on" ${st.paragraphImageEnabled?'selected':''}>Show</option><option value="off" ${!st.paragraphImageEnabled?'selected':''}>Hide</option></select></div><div class="field"><label>Paragraph image path</label><input id="ds_pimg" value="${attr(st.paragraphImage||'')}" placeholder="Media Library path"></div><div class="field"><label>Paragraph image position</label><select id="ds_pimg_pos"><option value="left" ${st.paragraphImagePosition==='left'?'selected':''}>Left</option><option value="right" ${st.paragraphImagePosition!=='left'?'selected':''}>Right</option><option value="top" ${st.paragraphImagePosition==='top'?'selected':''}>Top</option></select></div><div class="field"><label>Paragraph image width</label><input id="ds_pimg_width" value="${attr(st.paragraphImageWidth||'34%')}" placeholder="e.g. 34%"></div><div class="field"><label>Section CTA</label><select id="ds_cta"><option value="on" ${st.ctaEnabled?'selected':''}>Show</option><option value="off" ${!st.ctaEnabled?'selected':''}>Hide</option></select></div><div class="field"><label>CTA label</label><input id="ds_cta_label" value="${attr(st.ctaLabel||'Learn more')}"></div><div class="field"><label>CTA URL</label><input id="ds_cta_url" value="${attr(st.ctaUrl||'#')}"></div></div><div class="grid three"><div class="field"><label>Section background position</label><select id="ds_bg_position">${['center','top','bottom','left','right','center top','center bottom'].map(x=>`<option value="${x}" ${st.backgroundPosition===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Background size</label><select id="ds_bg_size">${['cover','contain','100% auto','auto 100%'].map(x=>`<option value="${x}" ${st.backgroundSize===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Custom CSS class (advanced)</label><input id="ds_custom" value="${attr(st.customClass||'')}" placeholder="Optional"></div></div><div class="card premium-subpanel"><h3>Premium button studio</h3><div class="grid three"><div class="field"><label>Button style — 15 presets</label>${designSelect('ds_btn_style',BUTTON_STYLES,STATE.appearance?.buttonStyle||'pill')}</div><div class="field"><label>Button animation</label>${animationSelect('ds_btn_anim',STATE.appearance?.buttonAnimation||'none')}</div><div class="field"><label>Button radius</label><input id="ds_btn_radius" value="${attr(STATE.appearance?.buttonRadius||10)}" placeholder="px"></div></div><div class="grid three"><div class="field"><label>Button background</label><input id="ds_btn_bg" type="color" value="${attr(STATE.appearance?.buttonBackground||'#E9C46A')}"></div><div class="field"><label>Button text</label><input id="ds_btn_text" type="color" value="${attr(STATE.appearance?.buttonText||'#14100A')}"></div><div class="field"><label>Button border</label><input id="ds_btn_border" type="color" value="${attr(STATE.appearance?.buttonBorder||'#C9A227')}"></div></div></div><div class="notice">Tip: keep the fixed DNA/chemical background as the portfolio-wide canvas. Section-specific backgrounds are optional and are blended so they do not create seams.</div></div>`}
function readDesignPanel(view){const st=getSectionStyle(view);st.layout=$('ds_layout').value;st.sectionMaxWidth=$('ds_width').value.trim();st.font=$('ds_font').value;st.headingFont=$('ds_heading_font').value;st.bodyColor=$('ds_body_color').value;st.headingColor=$('ds_heading_color').value;st.accentColor=$('ds_accent_color').value;st.fontSize=$('ds_size').value.trim();st.headingSize=$('ds_heading_size').value.trim();st.lineHeight=$('ds_line').value.trim();st.letterSpacing=$('ds_letter').value.trim();st.headingWeight=$('ds_weight').value;st.backgroundColor=$('ds_bg_color').value;st.backgroundImage=$('ds_bg_image').value.trim();st.backgroundOpacity=Number($('ds_bg_opacity').value);st.backgroundBlur=$('ds_bg_blur').value.trim();st.backgroundBrightness=Number($('ds_brightness').value);st.backgroundContrast=Number($('ds_contrast').value);st.backgroundSaturate=Number($('ds_saturate').value);st.overlayOpacity=Number($('ds_overlay_opacity').value);st.borderRadius=$('ds_radius').value.trim();st.shadow=$('ds_shadow').value.trim();st.hoverEnabled=$('ds_hover').value==='on';st.hoverColor=$('ds_hover_color').value;st.linkEnabled=$('ds_links').value==='on';st.linkUnderline=$('ds_underline').value==='on';st.paragraphImageEnabled=$('ds_pimg_enabled').value==='on';st.paragraphImage=$('ds_pimg').value.trim();st.paragraphImagePosition=$('ds_pimg_pos').value;st.paragraphImageWidth=$('ds_pimg_width').value.trim();st.ctaEnabled=$('ds_cta').value==='on';st.ctaLabel=$('ds_cta_label').value.trim();st.ctaUrl=$('ds_cta_url').value.trim();st.backgroundPosition=$('ds_bg_position')?.value||'center';st.backgroundSize=$('ds_bg_size')?.value||'cover';st.customClass=$('ds_custom')?.value.trim()||'';STATE.appearance.buttonStyle=$('ds_btn_style')?.value||STATE.appearance.buttonStyle||'pill';STATE.appearance.buttonAnimation=$('ds_btn_anim')?.value||STATE.appearance.buttonAnimation||'none';STATE.appearance.buttonRadius=Number($('ds_btn_radius')?.value)||10;STATE.appearance.buttonBackground=$('ds_btn_bg')?.value||STATE.appearance.buttonBackground||'#E9C46A';STATE.appearance.buttonText=$('ds_btn_text')?.value||STATE.appearance.buttonText||'#14100A';STATE.appearance.buttonBorder=$('ds_btn_border')?.value||STATE.appearance.buttonBorder||'#C9A227';STATE.appearance.sectionStyles[view]=st;return st}
async function saveDesignOnly(view){readDesignPanel(view);await save('appearance',`Update ${view} design settings`)}
function setupSectionEditor(view){
 const root=$('views'); if(!root || !root.children.length)return;
 const existing=root.querySelector('.editor-lockbar'); if(existing){setEditorLocked(true,view);return;}
 const bar=document.createElement('div');bar.className='editor-lockbar editor-locked';
 bar.innerHTML=`<div><strong>Section editor</strong><div class="status" id="editorStatus">Editing is locked. Click Edit Section before changing anything.</div></div><div class="row"><button class="btn gold" id="sectionEditBtn" type="button">✎ Edit Section</button><button class="btn" id="sectionSaveAllBtn" type="button" disabled>Save Changes</button><button class="btn" id="sectionCancelBtn" type="button">Cancel</button></div>`;
 root.insertBefore(bar,root.firstChild);
 if(DESIGN_LAYOUTS[view])root.insertAdjacentHTML('beforeend',designPanel(view));
 bar.querySelector('#sectionEditBtn').addEventListener('click',()=>setEditorLocked(false,view));
 bar.querySelector('#sectionSaveAllBtn').addEventListener('click',()=>saveSectionChanges(view));
 bar.querySelector('#sectionCancelBtn').addEventListener('click',()=>renderView(view));
 setEditorLocked(true,view);
}

function setEditorLocked(locked,view){
 const root=$('views'); if(!root)return;
 root.classList.toggle('editor-locked',locked);
 root.querySelectorAll('input,textarea,select').forEach(el=>{
   if(el.closest('.editor-lockbar'))return;
   el.disabled=locked;
 });
 root.querySelectorAll('button').forEach(btn=>{
   if(btn.closest('.editor-lockbar'))return;
   btn.disabled=locked;
 });
 root.querySelectorAll('a.btn').forEach(a=>{a.setAttribute('aria-disabled',locked?'true':'false');if(locked)a.style.pointerEvents='none';else a.style.pointerEvents=''});
 const bar=root.querySelector('.editor-lockbar');
 if(bar){bar.classList.toggle('editing',!locked);const st=bar.querySelector('#editorStatus');if(st)st.textContent=locked?'Editing is locked. Click Edit Section before changing anything.':'Editing enabled. Make your changes, then click Save Changes.';const edit=bar.querySelector('#sectionEditBtn');const all=bar.querySelector('#sectionSaveAllBtn');if(edit)edit.disabled=!locked;if(all)all.disabled=locked;}
}

async function saveSectionChanges(view){
 try{
  if(DESIGN_LAYOUTS[view])await saveDesignOnly(view);
  const fn={home:saveHome,about:saveAbout,contact:saveContact,appearance:saveAppearance,languages:saveLanguages,custom:saveCustomSections}[view];
  if(view==='navigation'){await saveNavigation();await saveHeaderDesign();return;}
  if(view==='cv'){if($('cv_url'))await saveCVUrl();if($('cv_sum'))await saveCVMeta();renderView('cv');return;}
  if(view==='education'||view==='research'||view==='publications'||view==='skills'||view==='experience'){
    const key=view==='skills'?'skills':view;
    await save(key,`Save ${view} section content and design`);
    renderView(view);return;
  }
  if(fn)await fn();
  else {toast('Section changes saved ✓');renderView(view)}
 }catch(e){toast(`Save failed: ${e.message||e}`,true)}
}

