function openPublication(i){const p=i===undefined?{slug:'',title:'',year:'',type:'Journal Article',venue:'',doi:'',externalUrl:'',pdfUrl:'',authors:'',projectSlug:'',presentation:{}}:STATE.publications[i];openModal(`<h2>${i===undefined?'Add':'Edit'} publication</h2><div class="grid two"><div class="field"><label>Title</label><textarea id="pub_title">${esc(p.title)}</textarea></div><div class="field"><label>Authors</label><textarea id="pub_authors">${esc(p.authors)}</textarea></div><div class="field"><label>Year</label><input id="pub_year" value="${attr(p.year)}"></div><div class="field"><label>Type</label><input id="pub_type" value="${attr(p.type)}"></div><div class="field"><label>Venue / journal</label><input id="pub_venue" value="${attr(p.venue)}"></div><div class="field"><label>DOI</label><input id="pub_doi" value="${attr(p.doi)}"></div><div class="field"><label>Authentic publication URL</label><input id="pub_ext" value="${attr(p.externalUrl)}"></div><div class="field"><label>PDF URL</label><input id="pub_pdf" value="${attr(p.pdfUrl)}"></div><div class="field"><label>Slug</label><input id="pub_slug" value="${attr(p.slug)}"></div><div class="field"><label>Linked project slug</label><input id="pub_project" value="${attr(p.projectSlug)}"></div></div>${itemStyleFields('pub_style',p.presentation||{})}<div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="savePublication(${i===undefined?'null':i})">Save publication</button></div>`)}
async function savePublication(i){const p={slug:$('pub_slug').value.trim()||$('pub_title').value.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title:$('pub_title').value.trim(),authors:$('pub_authors').value.trim(),year:$('pub_year').value.trim(),type:$('pub_type').value.trim(),venue:$('pub_venue').value.trim(),doi:$('pub_doi').value.trim(),externalUrl:$('pub_ext').value.trim(),pdfUrl:$('pub_pdf').value.trim(),projectSlug:$('pub_project').value.trim(),presentation:readItemStyle('pub_style',i===null?{}:(STATE.publications[i]?.presentation||{}))};if(i===null)STATE.publications.push(p);else STATE.publications[i]=p;await save('publications','Update publication');closeModal();renderView('publications')}
async function deletePublication(i){if(confirm('Delete this publication?')){STATE.publications.splice(i,1);await save('publications','Delete publication');renderView('publications')}}
function itemStyleFields(prefix,obj={}){return `<div class="card premium-subpanel"><h3>Advanced item presentation</h3><div class="grid three"><div class="field"><label>Title color</label><input id="${prefix}_tc" type="color" value="${attr(obj.titleColor||'#1A1712')}"></div><div class="field"><label>Body color</label><input id="${prefix}_bc" type="color" value="${attr(obj.bodyColor||'#6B6558')}"></div><div class="field"><label>Text size</label><input id="${prefix}_fs" value="${attr(obj.fontSize||'1rem')}"></div><div class="field"><label>Heading font</label>${designSelect(prefix+'_hf',DESIGN_FONTS,obj.headingFont||DESIGN_FONTS[0][1])}</div><div class="field"><label>Body font</label>${designSelect(prefix+'_bf',DESIGN_FONTS,obj.bodyFont||DESIGN_FONTS[0][1])}</div><div class="field"><label>Hover</label><select id="${prefix}_hover"><option value="on" ${obj.hover!==false?'selected':''}>On</option><option value="off" ${obj.hover===false?'selected':''}>Off</option></select></div></div><div class="grid two"><div class="field"><label>Image path</label><input id="${prefix}_img" value="${attr(obj.image||'')}"></div><div class="field"><label>Image click URL</label><input id="${prefix}_imgurl" value="${attr(obj.imageUrl||'')}"></div><div class="field"><label>Button label</label><input id="${prefix}_bl" value="${attr(obj.buttonLabel||'View details')}"></div><div class="field"><label>Button URL</label><input id="${prefix}_bu" value="${attr(obj.buttonUrl||'')}"></div><div class="field"><label>Button style</label>${designSelect(prefix+'_bs',BUTTON_STYLES,obj.buttonStyle||'pill')}</div><div class="field"><label>Button animation</label>${animationSelect(prefix+'_ba',obj.buttonAnimation||'none')}</div></div></div>`}
function readItemStyle(prefix,old={}){return {titleColor:$(`${prefix}_tc`)?.value||old.titleColor||'#1A1712',bodyColor:$(`${prefix}_bc`)?.value||old.bodyColor||'#6B6558',fontSize:$(`${prefix}_fs`)?.value.trim()||old.fontSize||'1rem',headingFont:$(`${prefix}_hf`)?.value||old.headingFont||DESIGN_FONTS[0][1],bodyFont:$(`${prefix}_bf`)?.value||old.bodyFont||DESIGN_FONTS[0][1],hover:$(`${prefix}_hover`)?.value!=='off',image:$(`${prefix}_img`)?.value.trim()||old.image||'',imageUrl:$(`${prefix}_imgurl`)?.value.trim()||old.imageUrl||'',buttonLabel:$(`${prefix}_bl`)?.value.trim()||old.buttonLabel||'View details',buttonUrl:$(`${prefix}_bu`)?.value.trim()||old.buttonUrl||'',buttonStyle:$(`${prefix}_bs`)?.value||old.buttonStyle||'pill',buttonAnimation:$(`${prefix}_ba`)?.value||old.buttonAnimation||'none'}}
function viewResearch(){$('views').innerHTML=`<div class="toolbar" style="justify-content:space-between;margin-bottom:12px"><div class="sub">Every project gets its own public detail page with methods, results and authentic publication/PDF links.</div><button class="btn gold" onclick="openResearch()">+ Add Research</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Project</th><th>Category</th><th>Year</th><th>Links</th><th>Actions</th></tr></thead><tbody>${(STATE.research||[]).sort((a,b)=>(a.order??0)-(b.order??0)).map((r,i)=>`<tr><td><strong>${esc(r.title)}</strong><div class="sub">${esc(r.slug)}</div></td><td>${esc(r.category)}</td><td>${esc(r.year)}</td><td>${r.externalUrl?'Publication ':''}${r.pdfUrl?'PDF ':''}${r.githubUrl?'GitHub':''}</td><td><div class="actions"><button class="icon" onclick="openResearch(${i})">Edit</button><button class="icon" onclick="duplicateResearch(${i})">Duplicate</button><button class="icon danger" onclick="deleteResearch(${i})">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`}
function mediaOptions(v=''){const imgs=STATE.images||[];return `<option value="">No image</option>`+imgs.filter(x=>x.type==='image').map(x=>`<option value="${attr(x.path)}" ${x.path===v?'selected':''}>${esc(x.name)}</option>`).join('')}
function openResearch(idx){const r=idx!==undefined?STATE.research[idx]:{slug:'',title:'',category:'',year:'',image:'',description:'',methods:'',tags:[],externalUrl:'',pdfUrl:'',githubUrl:'',featured:false,order:(STATE.research?.length||0)+1,publication:{journal:'',volume:'',pages:'',doi:'',year:''},results:[]};openModal(`<h2>${idx!==undefined?'Edit':'Add'} research project</h2><div class="grid two"><div class="field"><label>Title</label><input id="r_title" value="${attr(r.title)}"></div><div class="field"><label>Slug</label><input id="r_slug" value="${attr(r.slug)}" placeholder="unique-url-slug"></div><div class="field"><label>Category</label><input id="r_cat" value="${attr(r.category)}"></div><div class="field"><label>Year</label><input id="r_year" value="${attr(r.year)}"></div><div class="field"><label>Research image</label><select id="r_img">${mediaOptions(r.image)}</select></div><div class="field"><label>Tags, comma separated</label><input id="r_tags" value="${attr((r.tags||[]).join(', '))}"></div></div><div class="field"><label>Description</label><textarea id="r_desc">${esc(r.description)}</textarea></div><div class="field"><label>Methods</label><textarea id="r_methods">${esc(r.methods)}</textarea></div><div class="field"><label>Key results, one per line</label><textarea id="r_results">${esc((r.results||[]).join('\n'))}</textarea></div><h3>Publication metadata</h3><div class="grid three"><div class="field"><label>Journal</label><input id="r_journal" value="${attr(r.publication?.journal)}"></div><div class="field"><label>Volume / issue</label><input id="r_volume" value="${attr(r.publication?.volume)}"></div><div class="field"><label>Pages</label><input id="r_pages" value="${attr(r.publication?.pages)}"></div><div class="field"><label>DOI</label><input id="r_doi" value="${attr(r.publication?.doi)}"></div><div class="field"><label>Publication year</label><input id="r_py" value="${attr(r.publication?.year)}"></div></div><h3>Authentic resources</h3><div class="grid two"><div class="field"><label>Publication / external URL</label><input id="r_ext" value="${attr(r.externalUrl)}"></div><div class="field"><label>PDF URL</label><input id="r_pdf" value="${attr(r.pdfUrl)}"></div><div class="field"><label>GitHub URL</label><input id="r_gh" value="${attr(r.githubUrl)}"></div><div class="field"><label>Order</label><input id="r_order" type="number" value="${attr(r.order)}"></div></div>${itemStyleFields('r_style',r.presentation||{})}<div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="saveResearch(${idx===undefined?'null':idx})">Save project</button></div>`)}
async function saveResearch(idx){const old=idx===null?{}:STATE.research[idx];const r={slug:$('r_slug').value.trim()||$('r_title').value.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),title:$('r_title').value.trim(),category:$('r_cat').value.trim(),year:$('r_year').value.trim(),image:$('r_img').value,description:$('r_desc').value.trim(),methods:$('r_methods').value.trim(),results:$('r_results').value.split('\n').map(x=>x.trim()).filter(Boolean),tags:$('r_tags').value.split(',').map(x=>x.trim()).filter(Boolean),externalUrl:$('r_ext').value.trim(),pdfUrl:$('r_pdf').value.trim(),githubUrl:$('r_gh').value.trim(),featured:old.featured||false,order:Number($('r_order').value)||1,publication:{journal:$('r_journal').value.trim(),volume:$('r_volume').value.trim(),pages:$('r_pages').value.trim(),doi:$('r_doi').value.trim(),year:$('r_py').value.trim()},presentation:readItemStyle('r_style',old.presentation||{})};if(idx===null)STATE.research.push(r);else STATE.research[idx]=r;await save('research','Update research project');closeModal();renderView('research')}
