function viewEducation(){$('views').innerHTML=`<div class="toolbar" style="justify-content:flex-end"><button class="btn gold" onclick="openEducation()">+ Add education</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Degree</th><th>Institution</th><th>Period</th><th>Actions</th></tr></thead><tbody>${(STATE.education||[]).map((e,i)=>`<tr><td>${esc(e.degree)}</td><td>${esc(e.institution)}</td><td>${esc([e.startDate,e.current?'Present':e.endDate].filter(Boolean).join(' – '))}</td><td><button class="icon" onclick="openEducation(${i})">Edit</button><button class="icon danger" onclick="deleteEducation(${i})">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
function openEducation(i){const e=i===undefined?{degree:'',institution:'',location:'',startDate:'',endDate:'',current:false,description:'',logo:'',website:''}:STATE.education[i];openModal(`<h2>${i===undefined?'Add':'Edit'} education</h2><div class="grid two"><div class="field"><label>Degree</label><input id="e_deg" value="${attr(e.degree)}"></div><div class="field"><label>Institution</label><input id="e_inst" value="${attr(e.institution)}"></div><div class="field"><label>Location</label><input id="e_loc" value="${attr(e.location)}"></div><div class="field"><label>Start date</label><input id="e_start" value="${attr(e.startDate)}"></div><div class="field"><label>End date</label><input id="e_end" value="${attr(e.endDate)}"></div><div class="field switch"><input id="e_cur" type="checkbox" ${e.current?'checked':''}><label>Current</label></div></div><div class="field"><label>Description</label><textarea id="e_desc">${esc(e.description)}</textarea></div><div class="field"><label>Institution website</label><input id="e_web" value="${attr(e.website)}"></div>${itemStyleFields('e_style',e.presentation||{})}<div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="saveEducation(${i===undefined?'null':i})">Save</button></div>`)}
